$mode=$argv[1]??'--dry-run';$backupArg='';foreach($argv as$arg)if(str_starts_with($arg,'--backup='))$backupArg=substr($arg,9);
$targets=[
 ['table'=>'companies','pk'=>'id','columns'=>['gateway_api_key','whatsapp_token','smtp_password']],
 ['table'=>'payment_accounts','pk'=>'id','columns'=>['api_key','webhook_secret','credentials_encrypted','token_cache_encrypted']],
 ['table'=>'payment_account_certificates','pk'=>'id','columns'=>['certificate_encrypted','private_key_encrypted','chain_encrypted','password_encrypted']],
 ['table'=>'master_settings','pk'=>'id','columns'=>['mercadopago_access_token','evolution_master_api_key','smtp_password','cron_secret','cronjob_api_key']],
