$pdo=db();$legacy=[];foreach($targets as$t){$existing=[];foreach($pdo->query('SHOW COLUMNS FROM `'.$t['table'].'`')->fetchAll(PDO::FETCH_ASSOC)as$c)$existing[]=$c['Field'];$columns=array_values(array_intersect($t['columns'],$existing));if($columns===[])continue;$sql='SELECT `'.$t['pk'].'`,'.implode(',',array_map(static fn($c)=>'`'.$c.'`',$columns)).' FROM `'.$t['table'].'`';foreach($pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC)as$row)foreach($columns as$column){$value=$row[$column]??null;if(is_string($value)&&$value!==''&&!str_starts_with($value,COBX_SECRET_PREFIX))$legacy[]=['table'=>$t['table'],'pk'=>$t['pk'],'id'=>(string)$row[$t['pk']],'column'=>$column,'value'=>$value];}}
