if($mode==='--rollback'){if($backupArg===''||!is_file($backupArg))throw new RuntimeException('Informe --backup=CAMINHO_EXISTENTE.');$backup=json_decode((string)file_get_contents($backupArg),true,512,JSON_THROW_ON_ERROR);if(($backup['database']??'')!==(string)env('DB_DATABASE'))throw new RuntimeException('Backup pertence a outro banco.');$pdo->beginTransaction();try{foreach((array)($backup['records']??[])as$r)$pdo->prepare('UPDATE `'.$r['table'].'` SET `'.$r['column'].'`=? WHERE `'.$r['pk'].'`=?')->execute([$r['value'],$r['id']]);$pdo->commit();}catch(Throwable$e){$pdo->rollBack();throw$e;}echo json_encode(['mode'=>'rollback','restored'=>count($backup['records']??[])],JSON_PRETTY_PRINT),PHP_EOL;exit(0);}
